export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await fetchPosts({ revalidate: 300 })
  return posts.slice(0, 10).map((post) => ({ id: String(post.id) }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  let post: Post | null

  try {
    post = await fetchPost(id)
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  const description = post.body.substring(0, 160)
  return {
    title: post.title,
    description,
    openGraph: {
      title: `${post.title} - My Blog`,
      description,
    },
  }
}

export default async function BlogPost({ params }: BlogPostPageProps) {
  const { id } = await params
  let post: Post | null
  let comments: Comment[]

  try {
    const result = await Promise.all([fetchPost(id), fetchComments(id)])
    post = result[0]
    comments = result[1]
  } catch {
    notFound()
  }

  if (!post) {
    notFound()
  }

  return (
    <article>
      <RouterButton action="back">← Back</RouterButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface CreatePostInput {
  title: string
  content: string
}

function isCreatePostInput(value: unknown): value is CreatePostInput {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const input = value as Record<string, unknown>
  return (
    typeof input.title === 'string' &&
    Boolean(input.title) &&
    typeof input.content === 'string' &&
    Boolean(input.content)
  )
}

const posts: ApiPost[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

export async function GET(): Promise<Response> {
  return Response.json(posts)
}

export async function POST(request: Request): Promise<Response> {
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  if (!isCreatePostInput(body)) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: ApiPost = {
    id: Date.now(),
    title: body.title,
    content: body.content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}
interface UpdatePostInput {
  title?: string
  content?: string
}

interface RouteContext {
  params: Promise<{ id: string }>
}

function isUpdatePostInput(value: unknown): value is UpdatePostInput {
  if (typeof value !== 'object' || value === null) {
    return false
  }

  const input = value as Record<string, unknown>
  return (
    (input.title === undefined || typeof input.title === 'string') &&
    (input.content === undefined || typeof input.content === 'string')
  )
}

export async function GET(
  _request: Request,
  { params }: RouteContext
): Promise<Response> {
  const { id } = await params
  const numericId = Number.parseInt(id, 10)
  const post = {
    id: numericId,
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(
  request: Request,
  { params }: RouteContext
): Promise<Response> {
  const { id } = await params
  let body: unknown
  try {
    body = await request.json()
  } catch {
    return Response.json({ error: 'Invalid request body' }, { status: 400 })
  }

  if (!isUpdatePostInput(body)) {
    return Response.json({ error: 'Invalid request body' }, { status: 400 })
  }

  const updatedPost = {
    id: Number.parseInt(id, 10),
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(
  _request: Request,
  { params }: RouteContext
): Promise<Response> {
  const { id } = await params
  return Response.json({ message: `Post ${id} deleted successfully` })
}
