export interface Post {
  userId: number
  id: number
  title: string
  body: string
}

export interface Comment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

const POSTS_API = 'https://jsonplaceholder.typicode.com/posts'

async function fetchJson<T>(url: string, revalidate: number): Promise<T> {
  const response = await fetch(url, { next: { revalidate } })
  if (!response.ok) {
    throw new Error(`Failed to fetch data (${response.status})`)
  }
  return (await response.json()) as T
}

export async function fetchPosts(options: {
  limit?: number
  revalidate: number | null
}): Promise<Post[]> {
  const url = new URL(POSTS_API)
  if (options.limit !== undefined) {
    url.searchParams.set('_limit', String(options.limit))
  }

  if (options.revalidate === null) {
    const response = await fetch(url, { cache: 'no-store' })
    if (!response.ok) {
      throw new Error(`Failed to fetch posts (${response.status})`)
    }
    return (await response.json()) as Post[]
  }

  return fetchJson<Post[]>(url.toString(), options.revalidate)
}

export async function fetchPost(
  id: string,
  revalidate = 300
): Promise<Post | null> {
  const response = await fetch(`${POSTS_API}/${encodeURIComponent(id)}`, {
    next: { revalidate },
  })
  if (response.status === 404) {
    return null
  }
  if (!response.ok) {
    throw new Error(`Failed to fetch post (${response.status})`)
  }
  return (await response.json()) as Post
}

export function fetchComments(id: string, revalidate = 300): Promise<Comment[]> {
  return fetchJson<Comment[]>(
    `${POSTS_API}/${encodeURIComponent(id)}/comments`,
    revalidate
  )
}

